INSERT INTO aibrewgenius.batches (id, user_profile_id, brewfather_id, name, batch_no, status, brew_date, recipe_name, analysis_data, rapt_data, data, created_at, updated_at) VALUES ('7ce24782-8cce-4602-a335-ada8b8199443', 'self_hosted_profile', '2UKRHHnqW8t7C78sPreZVM67kNztJm', 'Brautag - Sud #9 (Bourbon Barrel Stout Nitro)', 9, 'Completed', 1758405600000, 'Bourbon Barrel Stout Nitro', NULL, NULL, '{"_id": "2UKRHHnqW8t7C78sPreZVM67kNztJm", "_rev": "OA6nyHhrBgIsSoOtsfp2H6QgkvAMPH", "cost": {"hops": 0, "miscs": 0, "total": 0, "yeasts": 0, "hopsShare": 0, "miscsShare": 0, "yeastsShare": 0, "fermentables": 0, "perBottlingLiter": 0, "fermentablesShare": 0}, "name": "Sud", "_init": true, "_type": "batch", "notes": [{"note": "", "type": "statusChanged", "status": "Completed", "timestamp": 1762334245615}, {"note": "", "type": "statusChanged", "status": "Fermenting", "timestamp": 1758486479340}, {"note": "", "type": "statusChanged", "status": "Brewing", "timestamp": 1758486357685}], "brewer": null, "events": [{"time": 1758441600000, "title": "Brautag - Sud #9 (Bourbon Barrel Stout Nitro)", "active": false, "dayEvent": true, "eventText": "Brautag", "eventType": "event-batch-brew-day", "notifyTime": 1758441600000, "description": "Brautag (Bourbon Barrel Stout Nitro)", "descriptionHTML": "Brautag (Bourbon Barrel Stout Nitro)"}, {"time": 1758355200000, "title": "Brautag - Erinnerung - Sud #9 (Bourbon Barrel Stout Nitro)", "active": false, "dayEvent": true, "eventText": "Brautag &mdash; Erinnerung", "eventType": "event-batch-brew-day-reminder", "notifyTime": 1758355200000, "description": "Ein geplanter Sud steht an (Bourbon Barrel Stout Nitro)", "descriptionHTML": "Ein geplanter Sud steht an (Bourbon Barrel Stout Nitro)"}, {"time": 1759305600000, "title": "Tag der Abfüllung - Sud #9 (Bourbon Barrel Stout Nitro)", "active": false, "dayEvent": true, "eventText": "Tag der Abfüllung", "eventType": "event-batch-bottling-day", "description": "Tag der Abfüllung (Bourbon Barrel Stout Nitro)", "descriptionHTML": "Tag der Abfüllung (Bourbon Barrel Stout Nitro)"}], "hidden": false, "recipe": {"fg": 1.007, "og": 1.029737142, "_ev": 2, "_id": "3AHjwbrhVveThSibOVeRw86pqKaTX5", "abv": 3.02, "ibu": 0, "_rev": "1VSoIoIX6rNgetb2RJ2mzKPwMzazIA", "data": {"mashVolume": 12.766900000000001, "strikeTemp": null, "topUpWater": 0, "hltWaterAmount": 14.32, "mashWaterAmount": 10.71, "mashFermentables": [{"_id": "new-QSE1MEWmcoFX2kZY6MY8TRNb5eoAAs", "use": "", "name": "Mangrove Jach''s Bourbon Barrel Stout Kit LME vorgehopft", "type": "Grain", "color": 2, "amount": 2.4, "origin": "", "supplier": "", "potential": null, "percentage": 78.18, "attenuation": null, "grainCategory": "Roasted", "potentialPercentage": null}, {"_id": "new-KNCwTHQJZ4MpN0RQ8psNDKxPPN9yQn", "use": "", "name": "Muntons Spraymalt Dark", "type": "Grain", "color": 2, "amount": 0.48, "origin": "", "supplier": "", "potential": null, "percentage": 15.64, "attenuation": null, "grainCategory": "Base", "potentialPercentage": null}, {"_id": "new-5a3wvBAl8OwwCJJP0SgIQ9H9u6Wukg", "use": "", "name": "Bourbon Oak Chips", "type": "Grain", "color": 2, "amount": 0.19, "origin": "", "supplier": "", "potential": null, "percentage": 6.19, "attenuation": null, "grainCategory": "Base", "potentialPercentage": null}], "totalWaterAmount": 25.03, "allDiastaticPower": false, "mashVolumeSurplus": 0, "otherFermentables": [], "spargeWaterAmount": 14.32, "totalDiastaticPower": 0, "mashFermentablesAmount": 3.07, "batchSpargeWaterAmount1": null, "batchSpargeWaterAmount2": null, "batchSpargeWaterAmount3": null, "batchSpargeWaterAmount4": null, "otherFermentablesAmount": 0}, "hops": [], "mash": {"_id": "default", "name": "High fermentability", "steps": [{"name": "", "type": "Temperature", "stepTemp": 65, "stepTime": 60}]}, "name": "Bourbon Barrel Stout Nitro", "path": "/", "tags": null, "type": "Extract", "_init": true, "_type": "recipe", "color": 2.6, "miscs": [], "notes": "Bourbon Barrel Stout (Nitro) – 20 L\n\nGesamtdauer (Starter → erster Antrunk): 6–8 Wochen\n\n⸻\n\nZutatenliste\n\t•\tMalzextrakte\n\t•\t2,5 kg Mangrove Jack’s Bourbon Barrel Stout Kit (LME, vorgehopft)\n\t•\t500 g Muntons Spraymalt Dark (DME)\n\t•\tHefe\n\t•\tWyeast 1728 Scottish Ale (Starter erforderlich)\n\t•\tHolz\n\t•\tBourbon Oak Chips (Kit-Beilage, optional 24 h in Bourbon einlegen)\n\t•\tWasseraufbereitung (für 25 L Brauwasser)\n\t•\tCalciumchlorid-Dihydrat (CaCl₂·2H₂O): 3,0 g\n\t•\tCalciumsulfat-Dihydrat (CaSO₄·2H₂O): 0,5 g\n\t•\tMagnesiumsulfat-Heptahydrat (MgSO₄·7H₂O): 0,5 g\n\n⸻\n\nHefestarter\n\t•\t130 g LME in 1 L Wasser, 15 Min kochen\n\t•\tauf 18–20 °C abkühlen, Hefe zugeben\n\t•\t18–24 Std. gären lassen\n\t•\tStarter am Brautag komplett in die Würze geben\n\n⸻\n\nBrautag – Sudplan\n\t1.\tWasser aufbereiten.\n\t2.\t3 L Wasser erhitzen, 2,5 kg LME + 500 g DME einrühren.\n\t3.\t10 Min sanft kochen (kein Überkochen!).\n\t4.\tMit kaltem Wasser auf 20 L auffüllen, Sauerstoff einrühren.\n\t5.\tAuf 18–20 °C kühlen.\n\t6.\tStarter + Hefe anstellen.\n\n⸻\n\nGärung\n\t•\tHauptgärung: 18–20 °C, 10–14 Tage\n\t•\tOG: 1.060–1.062\n\t•\tFG: 1.014–1.016\n\t•\tABV: ~6,1 %\n\t•\tHolz & Bourbon: Oak Chips nach 7 Tagen zugeben, 7–14 Tage ziehen lassen.\n\t•\tDiacetylrast: 20–22 °C für 2 Tage.\n\t•\tCold Crash: 2–3 Tage bei 2–4 °C.\n\n⸻\n\nKeg & Nitro-Karbonisierung\n\n1. Vorkarbonisierung (CO₂):\n\t•\t4 °C, 0,8 bar, 3–4 Tage (~1,2 Vol. CO₂)\n\n2. Nitro-Sättigung (70:30):\n\t•\t2,0–2,2 bar bei 4 °C, 5–7 Tage\n\n3. Ausschank:\n\t•\tStout-Faucet / Restrictor Tap\n\t•\t2,0–2,4 bar, 6–8 °C Serviertemperatur\n\n⸻\n\nLagerung & Reifung\n\t•\tErste Verkostung: 4 Wochen\n\t•\tOptimal: 2–3 Monate\n\n⸻\n\nVerkostungsnotizen\n\t•\tAroma: Bourbon, Vanille, Eiche, dunkle Schokolade, Kaffee\n\t•\tAntrunk: malzig-süß, cremig\n\t•\tAbgang: weich-röstig, Eichenholz\n\t•\tMundgefühl: samtig-cremig (Nitro)\n\n⸻\n\nKeg-Label\n\nName & Stil: Bourbon Barrel Stout (Nitro)\nAlkohol: ~6,1 % ABV\nMenge: 20 L\nBrautag: []\nAbfüllung: []\nErster Antrunk: ab 6 Wochen\nHauptzutaten: Malzextrakt, Spraymalt Dark, Oak Chips, Wyeast 1728\nKarbonisierung: 1,2 Vol. CO₂ + Nitro 70:30\nLagerhinweis: kühl & dunkel, mind. 8 Wochen", "water": {"mash": {"ph": 7.55, "_id": "BxaoyPTyb36ynD8b5nF6Ck46Np0eVQ", "_rev": "AQ2bA7xpf9WBq3WQge0aYKjsnHsiFm", "name": "Glattfelden", "type": "source", "anions": 1.279, "hidden": false, "sodium": 13.8, "calcium": 85.8, "cations": 6.507, "sulfate": 27.95, "_created": {"_seconds": 1711395249, "_nanoseconds": 482000000}, "_version": "2.10.9", "chloride": 24.7, "hardness": 295, "magnesium": 19.75, "soClRatio": 1.13, "_timestamp": {"_seconds": 1713092272, "_nanoseconds": 158000000}, "alkalinity": 0, "ionBalance": 34, "bicarbonate": 0, "_timestamp_ms": 1713092272158, "ionBalanceOff": true, "bicarbonateMeqL": 0, "residualAlkalinity": -72.89796, "residualAlkalinityMeqLCalc": -1.81937}, "meta": {"equalSourceTotal": true}, "total": {"ph": 7.55, "_id": "BxaoyPTyb36ynD8b5nF6Ck46Np0eVQ", "_rev": "AQ2bA7xpf9WBq3WQge0aYKjsnHsiFm", "name": "Glattfelden", "type": "source", "anions": 1.279, "hidden": false, "sodium": 13.8, "calcium": 85.8, "cations": 6.507, "sulfate": 27.95, "_created": {"_seconds": 1711395249, "_nanoseconds": 482000000}, "_version": "2.10.9", "chloride": 24.7, "hardness": 295, "magnesium": 19.75, "soClRatio": 1.13, "_timestamp": {"_seconds": 1713092272, "_nanoseconds": 158000000}, "alkalinity": 0, "ionBalance": 34, "bicarbonate": 0, "_timestamp_ms": 1713092272158, "ionBalanceOff": true, "bicarbonateMeqL": 0, "residualAlkalinity": -72.89796, "residualAlkalinityMeqLCalc": -1.81937}, "mashPh": 4.46, "source": {"ph": 7.55, "_id": "BxaoyPTyb36ynD8b5nF6Ck46Np0eVQ", "_rev": "AQ2bA7xpf9WBq3WQge0aYKjsnHsiFm", "name": "Glattfelden", "type": "source", "anions": 1.279, "hidden": false, "sodium": 13.8, "calcium": 85.8, "cations": 6.507, "sulfate": 27.95, "_created": {"_seconds": 1711395249, "_nanoseconds": 482000000}, "_version": "2.10.9", "chloride": 24.7, "hardness": 295, "magnesium": 19.75, "soClRatio": 1.13